//! 🧪️ The actual Worker callback receives the original narrow turn and returns its unique physical receipt before semantic access.
use semio_framework_job::*;
use semio_framework_job_worker::*;
use semio_framework_job_worker_authority::*;
use semio_framework_test_fixtures::fixture_text;
use semio_framework_value::{ValueError,ValueRefusalKind};
use std::mem::size_of;
use semio_framework_value_testing_allocator as _;
struct OriginalTurnProbe{source:[u8;17],output:[u8;17],copied:bool,closing:bool}
impl InteractiveJob for OriginalTurnProbe{
 fn step<'a>(&'a mut self,cx:&mut StepContext<'_>,_:&mut OriginalJobReturnClaim<'_>)->InteractiveJobStep<'a>{let result=(||{if self.copied{return JobOutcomeBorrow::admit_complete(cx,None,None).map_err(OriginalTurnFailure::from)}let grant=cx.retained_grant();if grant.maximum_items==0||grant.maximum_copy_bytes<17||grant.maximum_depth==0{return Ok(None)}self.output.copy_from_slice(&self.source);self.copied=true;cx.consume_fuel(1);cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:17,..Default::default()})?;Ok(None)})();InteractiveJobStep::from_callback(result)}
 fn borrow_outcome<'a>(&'a self,descriptor:&'a JobOutcomeDescriptor)->Result<JobOutcomeView<'a>,ValueError>{descriptor.complete(None,None)}
 fn begin_close(&mut self){self.closing=true;}
 fn close_step(&mut self,_:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{Ok(InteractiveJobCloseStep::Complete{progress:Default::default()})}
 fn terminal_is_empty(&self)->bool{self.closing}
 fn next_close_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(0)}
 fn next_close_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(0)}
 fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{Ok(0)}
 fn next_close_depth_demand(&self)->Result<usize,ValueError>{Ok(1)}
}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);assert!(!heap.overflowed);(value,(heap.requested_bytes,heap.released_bytes))}
fn policy(row:&serde_json::Value)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:row[0].as_u64().unwrap()as usize,maximum_copy_bytes:row[1].as_u64().unwrap()as usize,maximum_capacity_bytes:row[2].as_u64().unwrap()as usize,maximum_release_bytes:row[3].as_u64().unwrap()as usize,maximum_depth:row[4].as_u64().unwrap()as usize}}
fn admit<S:AdmittedWorkerJobSession<OriginalTurnProbe>>(caller:&mut OriginalJobFixtureCaller,params:BatchJobParams)->S{
 let law:serde_json::Value=serde_json::from_str(include_str!("../../🚪️session-admission/case.json")).unwrap();let mut admission=WorkerJobSessionAdmission::<OriginalTurnProbe,S>::new();let mut job=Some(OriginalTurnProbe{source:[7;17],output:[0;17],copied:false,closing:false});let mut params=Some(params);let mut output=None;
 for _ in 0..law["maximumTurns"].as_u64().unwrap(){if output.is_some(){break}let grant=caller.remaining_grant();caller.turn(grant,|cx|admission.advance(&mut job,&mut params,&mut output,cx)).unwrap();}
 assert!(admission.terminal_is_empty()&&job.is_none()&&params.is_none());output.expect("same-original staged session output")
}
#[test]
fn original_worker_turn_receipt_preserves_narrow_callback_and_exactly_once_recipient(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../🎟️turn/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/📐️.json")).unwrap();for(k,v)in law.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v);}let original=policy(&law["issued"]);let creation=policy(&law["policy"]);assert_eq!(original,policy(&law["effective"]));let stock=RetainedCloneGrant{maximum_items:20000,maximum_copy_bytes:16777216,maximum_capacity_bytes:16777216,maximum_release_bytes:16777216,maximum_depth:128};let mut caller=OriginalJobFixtureCaller::admit(OperationId(81291),Generation(3),stock,default_now_us,u64::MAX,20000);let params=BatchJobParams{operation:OperationId(81291),generation:Generation(3),cancel:caller.admit_alias(creation),config:BatchDriveConfig{retained:creation,site:"original-worker-turn",stage:InteractiveStage::InteractiveStep,fuel_per_step:1,step_budget_us:1000000},now_us:default_now_us};let mut session=admit::<MountedWorkerJobSession<OriginalTurnProbe>>(&mut caller,params);
 for denied in[RetainedCloneGrant{maximum_items:0,..original},RetainedCloneGrant{maximum_depth:0,..original}]{let(poll,heap)=observe(||caller.turn(denied,|cx|session.pump_one_for_interactive_turn(cx)).unwrap_or_else(|_|panic!("original denied opportunity preserves idle owner")));assert_eq!(poll,WorkerJobPoll::Idle);assert_eq!(heap,(0,0));assert!(session.take_checked_out_retained_step_receipt().is_none());assert!(session.checked_out_job().is_none());assert_eq!(session.poll(),WorkerJobPoll::Idle);}
 let(poll,heap)=observe(||caller.turn(original,|cx|session.pump_one_for_interactive_turn(cx)).unwrap_or_else(|_|panic!("original caller callback")));assert_eq!(poll,WorkerJobPoll::Outcome);assert_eq!(heap,(0,0));let address=session.checked_out_job().unwrap()as*const _;assert!(session.checked_out_outcome().is_err());assert!(!caller.turn(original,|cx|session.acknowledge_checked_out_outcome(cx)).unwrap());let(grant_view,progress_view)=session.checked_out_retained_step_receipt().unwrap();assert_eq!(*grant_view,original);assert_eq!(*progress_view,RetainedCloneProgress{copied_items:1,copied_bytes:17,..Default::default()});let view_pointer=progress_view as*const RetainedCloneProgress;assert_eq!(session.checked_out_retained_step_receipt().unwrap().1 as*const RetainedCloneProgress,view_pointer);let((effective,progress),heap)=observe(||session.take_checked_out_retained_step_receipt().unwrap());assert_eq!(heap,(0,0));assert_eq!(effective,original);assert_eq!(progress,RetainedCloneProgress{copied_items:1,copied_bytes:17,..Default::default()});assert!(progress.fits(original));assert!(session.take_checked_out_retained_step_receipt().is_none());assert!(session.checked_out_outcome().unwrap().is_none());assert_eq!(session.checked_out_job().unwrap()as*const _,address);assert_eq!(session.checked_out_job().unwrap().output,[7;17]);session.resume().unwrap();
 let(poll,heap)=observe(||caller.turn(original,|cx|session.pump_one_for_interactive_turn(cx)).unwrap_or_else(|_|panic!("original semantic callback")));assert_eq!(poll,WorkerJobPoll::Terminal);assert_eq!(heap,(0,0));assert!(session.checked_out_outcome().is_err());let(grant,receipt)=session.take_checked_out_retained_step_receipt().unwrap();assert_eq!(grant,original);assert_eq!(receipt,RetainedCloneProgress{copied_items:1,..Default::default()});assert!(matches!(session.checked_out_outcome().unwrap(),Some(JobOutcomeView::Complete{state:None,output:None,..})));assert_eq!(session.checked_out_job().unwrap()as*const _,address);for _ in 0..2{caller.turn(original,|cx|session.acknowledge_checked_out_outcome(cx)).unwrap();}session.begin_close();let mut turns=0;while !session.terminal_is_empty(){caller.close_owner(creation,&mut session).unwrap();turns+=1;assert!(turns<100000);}let(_,heap)=observe(||drop(session));assert_eq!(heap,(0,0));
 caller.retire(creation);
}

#[test]
fn original_batch_receipt_and_mutable_job_fence_preserve_none_semantics_and_original_authority(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../🎟️turn/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/📐️.json")).unwrap();for(k,v)in law.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v);}let original=policy(&law["issued"]);let creation=policy(&law["policy"]);let stock=RetainedCloneGrant{maximum_items:20000,maximum_copy_bytes:16777216,maximum_capacity_bytes:16777216,maximum_release_bytes:16777216,maximum_depth:128};let mut caller=OriginalJobFixtureCaller::admit(OperationId(81292),Generation(4),stock,default_now_us,u64::MAX,20000);let params=BatchJobParams{operation:OperationId(81292),generation:Generation(4),cancel:caller.admit_alias(creation),config:BatchDriveConfig{retained:creation,site:"original-batch-turn",stage:InteractiveStage::InteractiveStep,fuel_per_step:1,step_budget_us:1000000},now_us:default_now_us};let mut session=admit::<BatchJobSession<OriginalTurnProbe>>(&mut caller,params);let(poll,heap)=observe(||caller.turn(original,|cx|session.step_on_original_caller(cx)).unwrap());assert_eq!(poll,WorkerJobPoll::Outcome);assert_eq!(heap,(0,0));assert!(session.checkout_outcome());assert!(session.checked_out_job_mut().is_none());assert!(session.checked_out_outcome().is_err());let(grant,receipt)=session.take_checked_out_retained_step_receipt().unwrap();assert_eq!(grant,original);assert_eq!(receipt,RetainedCloneProgress{copied_items:1,copied_bytes:17,..Default::default()});assert!(session.take_checked_out_retained_step_receipt().is_none());assert!(session.checked_out_outcome().unwrap().is_none());assert_eq!(session.checked_out_job_mut().unwrap().output,[7;17]);session.resume().unwrap();assert_eq!(caller.turn(original,|cx|session.step_on_original_caller(cx)).unwrap(),WorkerJobPoll::Terminal);assert!(session.checkout_outcome());assert!(session.checked_out_job_mut().is_none());let(_,receipt)=session.take_checked_out_retained_step_receipt().unwrap();assert_eq!(receipt,RetainedCloneProgress{copied_items:1,..Default::default()});assert!(session.checked_out_job_mut().is_none());let denied=caller.turn(RetainedCloneGrant{maximum_items:0,..original},|cx|session.acknowledge_outcome(cx)).unwrap();assert!(!denied);assert_eq!(caller.receipt(),Default::default());assert!(session.checked_out_job_mut().is_none());for _ in 0..2{caller.turn(RetainedCloneGrant{maximum_copy_bytes:0,..original},|cx|session.acknowledge_outcome(cx)).unwrap();assert_eq!(caller.receipt(),RetainedCloneProgress{copied_items:1,..Default::default()});}assert!(session.checked_out_job_mut().is_some());session.begin_close();let mut turns=0;while !session.terminal_is_empty(){caller.close_owner(creation,&mut session).unwrap();turns+=1;assert!(turns<100000);}let(_,heap)=observe(||drop(session));assert_eq!(heap,(0,0));
 caller.retire(creation);
}

#[test]
fn original_context_cancel_alias_preserves_same_root_paid_metadata_zero_and_return_witness(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../../🎟️context/🛑️cancel/🤝️alias/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let turn:serde_json::Value=serde_json::from_str(fixture_text!("../../🎟️turn/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let creation=policy(&turn["policy"]);let stock=RetainedCloneGrant{maximum_items:20000,maximum_copy_bytes:16777216,maximum_capacity_bytes:16777216,maximum_release_bytes:16777216,maximum_depth:128};let mut caller=OriginalJobFixtureCaller::admit(OperationId(81294),Generation(6),stock,default_now_us,u64::MAX,20000);
 for row in law["cases"].as_array().unwrap(){let grant=policy(&row["grant"]);let mut alias=None;let pointer=caller.cancel()as*const CancelToken;let(admitted,heap)=observe(||caller.turn(grant,|cx|{assert_eq!(cx.original_cancel_token()as*const _,pointer);let admitted=cx.admit_original_cancel_alias(&mut alias)?;assert_eq!(cx.original_cancel_token()as*const _,pointer);Ok(admitted)}).unwrap());assert_eq!(heap,(0,0));assert_eq!(admitted,row["admitted"].as_bool().unwrap());assert_eq!(alias.is_some(),admitted);let expected=RetainedCloneProgress{copied_items:row["receipt"][0].as_u64().unwrap()as usize,..Default::default()};assert_eq!(caller.receipt(),expected);assert!(expected.fits(grant));if let Some(alias)=alias{let mut owner=semio_framework_async::CancelTokenRetirement::from_token(alias);assert!(owner.is_original_alias_witness(caller.cancel()));let(_,heap)=observe(||caller.turn(grant,|cx|{let turn=owner.return_alias_step(cx.original_cancel_token(),cx.retained_grant());let result=turn.result.map_err(|error|match error{semio_framework_async::CancelTokenRetirementError::Refused(error)=>error,semio_framework_async::CancelTokenRetirementError::Blocked(_)=>panic!("genuine original cancellation alias blocked")});let step=receive_original_retained_work(cx,semio_framework_value::RetainedWorkOutcome{result,work:turn.work})?;assert_eq!(step.progress(),RetainedCloneProgress{copied_items:1,..Default::default()});Ok(())}).unwrap());assert_eq!(heap,(0,0));assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));}}
 caller.retire(creation);
}
